import Foundation

enum AgentforceQuestionBank {
    static let all: [Question] = [
        Question(id: "1", question: "Sunrays Limited (SL) wants to incorporate CRM data as well-formatted JSON in a prompt to a large language model (LLM).\nWhat is an important consideration for this requirement?", options: [("A", "\"CRM data to JSON\" checkbox must be selected when creating a prompt template."), ("B", "Apex code can be used to return a JSON-formatted merge field."), ("C", "JSON format should be enabled in Prompt Builder Settings.")], questionType: .singleSelect, correctIndices: [1], explanation: "Apex code can be used to return a JSON-formatted merge field.\nProgrammatic Structure Control: Out-of-the-box merge fields in Salesforce Prompt Builder natively resolve to flat text or scalar values (like plain strings or numbers). When a business requirement mandates passing structured relational data as a well-formatted JSON block into an LLM prompt, you must use a programmatic solution."),
        Question(id: "2", question: "An AI Specialist at Sunrays Limited (SL) is trying to set up a new Field Generation prompt template. They take the following steps.\nCreate a new Field Generation prompt template.\nChoose Case as the object type.\nSelect the custom field AI_Analysis__c as the target field.\nAfter creating the prompt template, the AI Specialist saves, tests and activates it. However, when they go to a case record, the AI Analysis field does not show the (Spatial) icon on the Edit pencil.When the AI Specialist was editing the field, it was behaving as a normal field.\nWhich critical step did the AI Specialist miss?", options: [("A", "They forgot to edit the Lightning page layout and associate the field to a prompt template."), ("B", "They forgot that the Case object is not supported for field generation as Einstein service replies should be used instead."), ("C", "They forgot to reactivate the lightning page layout for the Case object after activating the Field Generation prompt template.")], questionType: .singleSelect, correctIndices: [0], explanation: "They forgot to edit the Lightning page layout and associate the field to a prompt template.\nThe Two-Step Configuration Bind: Activating a Field Generation prompt template inside Prompt Builder is only the first part of the deployment lifecycle. To surface the generative AI action button (the Einstein magic wand/spatial icon) on a live record page for end-users, an administrator must complete the configuration loop by updating the user interface layout."),
        Question(id: "3", question: "Sunrays Limited (SL) dealing with a high volume of chat inquiries, implements Einstein Work Summaries to boost productivity.\nAfter an agent-customer conversation, which additional information does Einstein generate and fill, apart from the \"summary\"?", options: [("A", "Issue and Resolution"), ("B", "Draft Survey Request Email"), ("C", "Sentiment Analysis and Emotion Detection")], questionType: .singleSelect, correctIndices: [0], explanation: "Issue and Resolution"),
        Question(id: "4", question: "Sunrays Limited (SL) is implementing generative AI and wants to leverage a prompt template to provide responses to customers that give personalized product recommendations to website visitors based on their browser history.\nWhich initial step should SL take to ensure the chatbot can deliver accurate recommendations?", options: [("A", "Collect and analyze browsing data."), ("B", "Design universal product recommendations."), ("C", "Write a response script for the chatbot.")], questionType: .singleSelect, correctIndices: [0], explanation: "Collect and analyze browsing data."),
        Question(id: "5", question: "An AI Specialist created a custom Agent action, but it is not being picked up by the planner service in the correct order.\nWhich adjustment should the AI Specialist make in the custom Agent action instructions for the planner service to work as expected?", options: [("A", "Specify the LLM model provider and version to be used to invoke the action."), ("B", "Specify the profiles on custom permissions allowed to invoke the action."), ("C", "Specify the dependent actions with the reference to the action API name.")], questionType: .singleSelect, correctIndices: [2], explanation: "Specify the dependent actions with the reference to the action API name.\nIn the Agentforce Atlas Reasoning Engine, the \"planner service\" (the part of the AI that decides which steps to take) uses your natural language instructions to build an execution plan. If actions are being picked up in the wrong order, it's because the AI doesn't understand the relationship or sequence between them."),
        Question(id: "6", question: "Sunrays Limited (SL) wants to leverage Generative AI Salesforce functionality to reduce Service Agent handling time by providing recommended replies based on the existing Knowledge articles.\nOn which AI capability should SL train the service agents?", options: [("A", "Knowledge Replies"), ("B", "Case Replies"), ("C", "Service Replies")], questionType: .singleSelect, correctIndices: [0], explanation: "Knowledge Replies\nKnowledge Replies is the Einstein Generative AI capability that generates recommended responses for service agents by grounding responses in the organization’s Knowledge articles."),
        Question(id: "7", question: "TRUE or FALSE: A Toxicity Score of 1 means VERY Toxic?", options: [("A", "True"), ("B", "False")], questionType: .singleSelect, correctIndices: [0], explanation: "Answer:\nTRUE\nA Toxicity Score of 1 means VERY Toxic?\nToxicity Categories (Hate Speech, Harassment, Sexual Content, Violence): For these specific objectionable behavior categories, scores range from 0 to 1, where 1 indicates the highest confidence/severity of toxicity. Therefore, a toxicity category score of 1 means the content is the most toxic for that classification."),
        Question(id: "8", question: "TRUE or FALSE: A Safety Score of 0 means completely SAFE?", options: [("A", "True"), ("B", "False")], questionType: .singleSelect, correctIndices: [1], explanation: "Answer:\nFALSE\nA Safety Score of 0 means completely UNSAFE\nThe Safety Category: Conversely, the high-level baseline safety score also ranges from 0 to 1, but on an inverted index where 1 means completely safe (scores between 0.5 and 1 are deemed compliant)."),
        Question(id: "9", question: "An AI specialist has grounded a prompt template with a related list. During User Acceptance Testing (UAT) users are not getting the correct responses.\nWhat is causing this issue?", options: [("A", "The related list is read-only."), ("B", "The related list prompt template option is not enabled."), ("C", "The related list is not on the parent object's page layout.")], questionType: .singleSelect, correctIndices: [2], explanation: "The related list is not on the parent object's page layout."),
        Question(id: "10", question: "Sunrays Limited (SL) wants to incorporate the current order fulfillment status into a prompt for a large language model (LLM). The order status is stored in the external enterprise resource planning (ERP) system.\nWhich data grounding technique should the AI Specialist recommend?", options: [("A", "External Services Merge Fields"), ("B", "Apex Merge Fields"), ("C", "External Object Record Merge Fields")], questionType: .singleSelect, correctIndices: [2], explanation: "External Object Record Merge Fields\nData grounding ensures the Large Language Model has access to the most current and relevant information. In Salesforce, one recommended approach is to use External Objects (via Salesforce Connect) when data resides outside of Salesforce."),
        Question(id: "11", question: "How does Secure Data Retrieval ensure that only authorized users can access necessary Salesforce data for dynamic grounding?", options: [("A", "Retrieves Salesforce data based on the \"Run As\" user's permissions"), ("B", "Retrieves Salesforce data based on the Prompt template's object permissions"), ("C", "Retrieves Salesforce data based on the user's permissions executing the prompt")], questionType: .singleSelect, correctIndices: [2], explanation: "Retrieves Salesforce data based on the user's permissions executing the prompt"),
        Question(id: "12", question: "After creating a foundation model in Einstein Studio, which hyperparameter should an AI Specialist use to adjust the balance between consistency and randomness a response?", options: [("A", "Variability"), ("B", "Presence Penalty"), ("C", "Temperature")], questionType: .singleSelect, correctIndices: [2], explanation: "Temperature\nThe Temperature hyperparameter controls the randomness of model outputs:\nLow Temperature (e.g., 0.2): More deterministic, professional and consistent responses.\nHigh Temperature (e.g., 1.0): More creative, varied responses.\n\nTemperature: A Hyperparameter that controls the randomness of model outputs.\nLow Temperature (e.g., 0.2): More deterministic, professional and consistent responses.\nHigh Temperature (e.g., 1.0): More creative, varied responses.\n\nPresence Penalty: A hyperparameter is used to control word repetition. \nIt applies a mathematical penalty to tokens that have already appeared in the generated text string at least once, encouraging the model to branch out to entirely new conversational concepts. \nIt does not directly manage the global spectrum between predictable consistency and random output generation.\n\nVariability: \"Variability\" describes the conceptual variance or behavior observed in a model's outputs. It is a general descriptive trait rather than an actual technical hyperparameter option found inside the Einstein Studio LLM configuration panels."),
        Question(id: "13", question: "TRUE OR FALSE:\nService AI Grounding supports Rich Text Area type fields", options: [("A", "True"), ("B", "False")], questionType: .singleSelect, correctIndices: [1], explanation: "Answer:\nFALSE\nService AI Grounding DOES NOT support Rich Text Area type fields\nService AI Grounding only supports String and Text Area type fields"),
        Question(id: "14", question: "Sunrays Limited (SL) sales team engages in numerous video sales calls with prospects across the nation. Sales management wants an easy way to understand key information such as deal terms or customer sentiments.\nWhich Einstein Generative AI feature should an AI specialist recommend for this request?", options: [("A", "Einstein Conversation Insights"), ("B", "Einstein Call Summaries"), ("C", "Einstein Video KPI")], questionType: .singleSelect, correctIndices: [1], explanation: "Einstein Call Summaries\nEinstein Call Summaries is the best option for this scenario because it leverages Salesforce's AI capabilities to automatically summarize key details of video or voice calls.\nIt includes details like deal terms, customer sentiments, follow-up tasks, and other crucial information."),
        Question(id: "15", question: "An Agentforce specialist wants to leverage the Record Snapshots grounding feature in a prompt template.\nWhat preparations are required?", options: [("A", "Create a field set for all the fields to be grounded"), ("B", "Configure page layout of the master record type"), ("C", "Enable and configure dynamic form for the object")], questionType: .singleSelect, correctIndices: [0], explanation: "Create a field set for all the fields to be grounded\nTo use the Record Snapshots grounding feature in a prompt template, you must create a field set that includes all fields required for grounding."),
        Question(id: "16", question: "Sunrays Limited (SL) users are complaining that agent answers are not satisfactory. The agent is using PDF files as a knowledge source.\nHow should SL troubleshoot this issue?", options: [("A", "Analyze the data mapping between source fields and Data Cloud object fields."), ("B", "Verify the retriever's filter criteria and data source connection."), ("C", "Check that the agent has the PDF the field permission access for the data library.")], questionType: .singleSelect, correctIndices: [1], explanation: "Verify the retriever's filter criteria and data source connection.\nThe Retriever acts as the bridge between the agent and the Data Cloud Search Index.\nRetriever Filter Criteria: Just like a Salesforce report, a retriever can have filters (e.g., \"Only search articles where Status = Published\"). If these filters are too restrictive, the agent will miss the specific PDF content it needs to answer the question, leading to a \"hallucination\" or a generic \"I don't know\" response.\nData Source Connection: PDFs in Data Cloud are often stored in external \"Blob Stores\" (like Amazon S3, Google Cloud Storage, or SharePoint). If the connection to these sources is broken or the Data Stream has failed to refresh, the agent will be searching against outdated or non-existent data."),
        Question(id: "17", question: "Sunrays Limited (SL) is deploying two agents simultaneously: an internal Sales Productivity Agent for employees and a customer facing Service Agent on its Experience Cloud site.An Agentforce Specialist is configuring permissions and needs to understand the correct security context for each.\nWhich statement accurately describes the execution model?", options: [("A", "The customer-facing Service Agent inherits the security context of the Experience Cloud site's guest user profile by default, requiring guest profile object permissions to be configured for all actions the agent executes."), ("B", "The internal Sales Productivity Agent executes actions using the authenticated Salesforce employee's own permissions, while the customer-facing Service Agent executes actions as a dedicated Einstein Service Agent User with its own permission set."), ("C", "Both the internal Sales Productivity Agent and the customer-facing Service Agent execute actions as a dedicated Einstein Service Agent User with its own permission set that is configured as required for the agent.")], questionType: .singleSelect, correctIndices: [1], explanation: "The internal Sales Productivity Agent executes actions using the authenticated Salesforce employee's own permissions, while the customer-facing Service Agent executes actions as a dedicated Einstein Service Agent User with its own permission set."),
        Question(id: "18", question: "An Agentforce Specialist wants to leverage the Record Snapshots grounding feature in a prompt template.  What preparations are required?", options: [("A", "Create a field set for all the fields to be grounded"), ("B", "Configure page layout of the master record type"), ("C", "Enable and configure dynamic form for the object")], questionType: .singleSelect, correctIndices: [0], explanation: "Create a field set for all the fields to be grounded\nTo use the Record Snapshots grounding feature in a prompt template, you must create a field set that includes all fields required for grounding."),
        Question(id: "19", question: "Sunrays Limited (SL) is deploying a new customer service agent using Agent Script. The Agentforce Specialist needs to update conversational state, navigate between different subagent (formerly known as a topic), and hand off conversations to a human agent when necessary. To minimize technical debt, the Agentforce Specialist wants to implement these capabilities without building any custom backend code.\nWhich statement correctly describes how the Agentforce Specialist can implement these specific requirements?", options: [("A", "The Agentforce Specialist can use @utils.setVariables, @utils.transition, and @utils.escalate directly."), ("B", "The Agentforce Specialist can use most utilities directly, but @utils.escalate requires a custom Apex class to define the escalation queue."), ("C", "The Agentforce Specialist can use most utilities out of the box, but @utils.transition requires a flow to define the target subagent at runtime.")], questionType: .singleSelect, correctIndices: [0], explanation: "The Agentforce Specialist can use @utils.setVariables, @utils.transition, and @utils.escalate directly.\nSalesforce natively provides an out-of-the-box @utils namespace that acts as pre-built tool handlers for standard operational requirements:"),
        Question(id: "20", question: "Sunrays Limited (SL) is configuring a customer service agent and needs to restrict a specific \"Process Refund\" action so that it is only visible to the reasoning engine when a customer's account is flagged as active. An Agentforce Specialist is writing the available when clause in Agent Script to evaluate the @variables.IsActive variable.\nWhich operator should the Agentforce Specialist use for this condition?", options: [("A", "The Agentforce Specialist must use the = operator; Agent Script uses == strictly for comparison in conditionals."), ("B", "Both and are valid and interchangeable; the Agentforce Specialist can use either operator to evaluate conditional logic in Agent Script."), ("C", "The Agentforce Specialist must use the == operator; Agent Script uses for both variable assignment and condition comparison.")], questionType: .singleSelect, correctIndices: [0], explanation: "The Agentforce Specialist must use the  = operator; Agent Script uses == strictly for comparison in conditionals.\n== (Comparison Operator): This operator is used strictly to evaluate whether an expression or variable equates to a specific state or boolean literal (e.g., available when @variables.IsActive == True). It returns a boolean outcome (True or False) to the reasoning engine.\n= (Assignment Operator): In contrast, the single equals sign = is reserved exclusively for binding inputs or modifying variable values within logic instructions (for example, using the with constraint or a set command like set @variables.Status = \"Processed\")."),
        Question(id: "21", question: "During retrieval augmented generation (RAG) quality testing, an Agentforce Specialist notices that tabular information from a custom Data 360 Document Ingestion Pipeline is losing its context because the data is scattered across multiple separate chunks.\nWhat is the most appropriate approach to resolve this?", options: [("A", "Change the search index's parser from the default to Docling."), ("B", "Use an ensemble retriever to stitch multiple chunks back together dynamically."), ("C", "Switch the search index configuration to use only keyword search scoring.")], questionType: .singleSelect, correctIndices: [0], explanation: "Change the search index's parser from the default to Docling.\nDocling is a purpose-built document understanding framework designed to recognize structural layout hierarchies (such as tables, embedded headers, multi-column divisions, and bounded text zones).\nBy switching the default search index parser to Docling, the indexing pipeline processes complex data objects as cohesive, structured tables rather than flat, continuous paragraphs."),
        Question(id: "22", question: "An Agentforce Specialist is trying to troubleshoot a reported issue from an end user and they do not see the session in the Processed Sessions tab of Agentforce Observability.\nWhat should the specialist take into consideration?", options: [("A", "The agent has not yet been registered in the Observability app so no sessions are processed."), ("B", "The session is queued to be processed and can be viewed on the Unprocessed Sessions tab."), ("C", "Sessions are batched on a 24-hour rolling process and the logs must be checked again the next day.")], questionType: .singleSelect, correctIndices: [1], explanation: "The session is queued to be processed and can be viewed on the Unprocessed Sessions tab."),
        Question(id: "23", question: "Which statement correctly describes hybrid reasoning in Agentforce Agent Script?", options: [("A", "Hybrid reasoning uses multiple large language model (LLM) models simultaneously, with one model handling conversational responses and another model executing deterministic business logic through Flow integration."), ("B", "Hybrid reasoning requires Canvas View for declarative instructions and Script View for procedural instructions, as each editor provides different capabilities for the respective instruction types."), ("C", "Hybrid reasoning combines declarative natural language instructions that allow large language model (LLM) interpretation with procedural instructions using the '->' prefix that enforce guaranteed execution order.")], questionType: .singleSelect, correctIndices: [2], explanation: "Hybrid reasoning combines declarative natural language instructions that allow large language model (LLM) interpretation with procedural instructions using the '->' prefix that enforce guaranteed execution order."),
        Question(id: "24", question: "Sunrays Limited (SL) has built a Service Agent for its hospitality brand grounded on a knowledge data library containing 200 FAQ articles covering reservations, amenities, and cancellation policies. The project team estimates that manually authoring test cases to achieve adequate knowledge coverage would take 3 weeks. A junior administrator proposes that Testing Center can significantly accelerate this process.\nWhich step should an Agentforce Specialist take to generate a comprehensive initial test suite without manual authoring of individual test cases?", options: [("A", "Upload test cases."), ("B", "Generate test cases based on the knowledge available to the agent."), ("C", "Generate test cases based on subagent (formerly known as a topic) and actions")], questionType: .singleSelect, correctIndices: [1], explanation: "Generate test cases based on the knowledge available to the agent.\nHow Knowledge-Based Generation Works: The Testing Center features an automated generative capabilities engine. When you select the option to generate test cases based on the agent's available knowledge, the system scans the underlying active Data Libraries and Knowledge data sources assigned to that agent."),
        Question(id: "25", question: "An Agentforce Specialist is working declaratively on version 4 of a prompt template which is significantly different than the previous version 3. A bug is then identified in version 3 and requires a hotfix to be deployed to production immediately by another team. The team will deploy this change as a new version.\nWhat should the specialist do to ensure that their work on the latest version is not lost and does not conflict with the new version?", options: [("A", "Create a new prompt template with the bug fix, update all references to the new version, and delete the old prompt template."), ("B", "Save their work in version 4, and allow the template to be deployed with a new version 5 containing the fix."), ("C", "Copy and paste version 4 into a backup file or version-control alternative, and allow the other team to overwrite the contents of version 4 with the bug fixed version.")], questionType: .singleSelect, correctIndices: [1], explanation: "Save their work in version 4, and allow the template to be deployed with a new version 5 containing the fix."),
        Question(id: "26", question: "An Agentforce Specialist is setting up Salesforce Knowledge as the data source for a Data Library and must select \"Identifying Fields\" to help Agentforce locate the right information. The Knowledge article contents are rich, detailed, and quite long.\nWhat should the Agentforce Specialist use as Identifying Fields?", options: [("A", "The main contents of the article to ensure the most relevant article is used"), ("B", "Any text or text area fields that provide a concise summary of the article"), ("C", "Any standard or custom formula field that contains a suitable concatenated key")], questionType: .singleSelect, correctIndices: [1], explanation: "Any text or text area fields that provide a concise summary of the article\nThe Role of Identifying Fields: Identifying fields are used by the Agentforce reasoning engine during the initial chunk retrieval and search result display phases. \nWhy Concise Summaries are Required: Because Knowledge articles can be incredibly long, rich, and detailed, mapping the massive main body text as an identifying field causes token bloat and dilutes the search relevance engine. Instead, Salesforce documentation recommends selecting concise fields (such as the Title, Summary, or short text area fields) as Identifying Fields"),
        Question(id: "27", question: "Sunrays Limited (SL) wants to enable it sales team to get insights into product and competitor names mentioned during calls.\nHow should SL mention this requirement?", options: [("A", "Enable Einstein Conversation Insights, assign permission sets, define recording managers, and customize insights with up to 50 competitor names."), ("B", "Enable Einstein Conversation Insights, connect a recording provider, assign permission sets and customize insights with up to 25 products."), ("C", "Enable Einstein Conversation Insights, enable sales recording, assign permission sets and customize insights with up to 50 products.")], questionType: .singleSelect, correctIndices: [1], explanation: "Enable Einstein Conversation Insights, connect a recording provider, assign permission sets and customize insights with up to 25 products."),
        Question(id: "28", question: "Sunrays Limited (SL) wants to reduce overall agent handling time by minimizing the time spent typing routine answers for common questions in chat and reducing the post-chat analysis by suggesting values for case fields.\nWhich combination of Einstein for Service features enables this effort?", options: [("A", "Einstein Service Replies and Work Summaries."), ("B", "Einstein Reply Recommendations and Case Summaries"), ("C", "Einstein Reply Recommendations and Case Classification")], questionType: .singleSelect, correctIndices: [2], explanation: "Einstein Reply Recommendations and Case Classification"),
        Question(id: "29", question: "In Model Playground, which hyperparameters of an existing Salesforce-enabled foundational model can an AI Specialist change?", options: [("A", "Temperature, Frequency Penalty, Presence Penalty"), ("B", "Temperature, Top-k sampling, Presence Penalty"), ("C", "Temperature, Frequency Penalty, Output Tokens")], questionType: .singleSelect, correctIndices: [0], explanation: "Temperature, Frequency Penalty, Presence Penalty"),
        Question(id: "30", question: "Sunrays Limited (SL) needs a tool that can analyze voice and video call records to provide insights on competitor mentions, coaching opportunities, and other key information. The goal is to enhance the team's performance by identifying areas for improvement and competitive intelligence.\nWhich feature provides insights about competitor mentions and coaching opportunities?", options: [("A", "Call Summaries"), ("B", "Einstein Sales Insights"), ("C", "Call Explorer")], questionType: .singleSelect, correctIndices: [2], explanation: "Call Explorer\nCall Explorer is a generative AI powered feature within Einstein Conversation Insights (ECI). It allows sales managers and reps to interact directly with a conversational interface to query voice and video call records using natural language (e.g., \"What competitors did the customer mention?\" or \"What were the primary objections raised?\")."),
        Question(id: "31", question: "Sunrays Limited (SL) has a mature Salesforce org with a lot of data in cases and Knowledge articles. SL is concerned that there are many legacy fields with data that might not be applicable for Einstein AI to draft accurate email responses.\nWhich solution should SL use to ensure Einstein AI can draft responses from a defined data source?", options: [("A", "Service AI Grounding"), ("B", "Work Summaries"), ("C", "Service Replies")], questionType: .singleSelect, correctIndices: [0], explanation: "Service AI Grounding\nService AI Grounding is the specific configuration tool that allows an admin to precisely define which fields Einstein should treat as the \"source of truth.\""),
        Question(id: "32", question: "Sunrays Limited (SL) is implementing Service AI grounding to enhance its customer service operations. SL wants to ensure that its AI-generated responses are grounded in the most relevant data sources. The team needs to configure the system to include all supported objects for grounding.\nWhich objects should SL select to configure Service AI Grounding?", options: [("A", "Case, Knowledge and Case Notes"), ("B", "Case and Knowledge"), ("C", "Case, Case Emails and Knowledge")], questionType: .singleSelect, correctIndices: [1], explanation: "Case and Knowledge"),
        Question(id: "33", question: "Sunrays Limited (SL) wants to use an external large language model (LLM) in Prompt Builder.\nWhat should an AI specialist recommend?", options: [("A", "Use Apex to connect to an external LLM and ground the prompt."), ("B", "Use BYO-LLM functionality in Einstein Studio."), ("C", "Use Flow and External Services to bring data from an external LLM.")], questionType: .singleSelect, correctIndices: [1], explanation: "Use BYO-LLM functionality in Einstein Studio.\nBring Your Own Large Language Model (BYO-LLM) functionality in Einstein Studio allows organizations to integrate and use external large language models (LLMs) within the Salesforce ecosystem."),
        Question(id: "34", question: "Sunrays Limited (SL) implements Custom Agent Actions to enhance its customer service operations. The development team needs to understand the core components of a custom Agent Action to ensure proper configuration and functionality.\nWhat should the development team review in the Custom Agent Action configuration to identify one of the core components of a Custom Agent Action?", options: [("A", "Instructions"), ("B", "Output Types"), ("C", "Action Triggers")], questionType: .singleSelect, correctIndices: [0], explanation: "Instructions"),
        Question(id: "35", question: "An AI Specialist wants to include data from the response of external service invocation (REST API callout) into the prompt template.\nHow should the AI Specialist meet this requirement?", options: [("A", "Convert the JSON to an XML merge field."), ("B", "Use External Service Record merge fields."), ("C", "Use \"Add Prompt Instructions\" flow element.")], questionType: .singleSelect, correctIndices: [1], explanation: "Use External Service Record merge fields.\nNative External Data Integration: When an AI Specialist needs to ground a prompt template with real-time data residing outside of Salesforce (via a REST API callout), they leverage Salesforce External Services. Once an External Service is registered, its structured response schema becomes natively available within Prompt Builder."),
        Question(id: "36", question: "Sunrays Limited (SL) has a Legacy system that needs to integrate with Salesforce. SL wishes to create a digest of account action plans using the generative API feature.\nWhich API service should SL use to meet this requirement?", options: [("A", "Rest API"), ("B", "Metadata API"), ("C", "Soap API")], questionType: .singleSelect, correctIndices: [0], explanation: "Rest API\nTo interact with Salesforce’s generative AI features—specifically to trigger prompt templates and retrieve AI-generated content from an external \"Legacy\" system—the Salesforce Connect REST API is the primary and most modern interface used.\nThe Einstein generative features are exposed via specific REST resources (endpoints)."),
        Question(id: "37", question: "Sunrays Limited (SL) is preparing and defining success criteria for Agentforce Testing Center test cases.\nWhich details should SL specify as the expected output to ensure the tests accurately reflect the agent's functionality?", options: [("A", "Expected Topic API Name"), ("B", "Expected Flow API Name"), ("C", "Expected Prompt Template Name")], questionType: .singleSelect, correctIndices: [0], explanation: "Expected Topic API Name\nBecause an agent organizes its tools and actions under distinct functional categories called Topics, verifying the Expected Topic API Name ensures that the agent's routing mechanism is selecting the correct conversational domain"),
        Question(id: "38", question: "A Service Agent at Sunrays Limited (SL) is designed to help customers resolve issues by searching against knowledge articles.Knowledge articles have PDF attachments that add critical details. UC reports that the agent provides excellent summaries of the knowledge articles, but seems completely unaware of the PDF attachments.\nHow should an Agentforce Specialist configure the Data Cloud search index to include the content of these attached files?", options: [("A", "Increase article chunk size and token limits for Knowledge indexing so larger contexts capture attachment references."), ("B", "Enable 'Include Related Attachments' for Knowledge__kav and map the ContentDocumentLink unstructured data model object (UDMO)."), ("C", "Use Data Cloud's 'Include Attachments' option and select the ContentDocumentVersion unstructured data model object (UDMO).")], questionType: .singleSelect, correctIndices: [2], explanation: "Use Data Cloud's 'Include Attachments' option and select the ContentDocumentVersion unstructured data model object (UDMO)."),
        Question(id: "39", question: "After an agent selects a topic, what is an important factor the reasoning engine uses to select the action?", options: [("A", "The priority given to each action"), ("B", "The explicit order of actions in the topic"), ("C", "The name and instructions of the actions")], questionType: .singleSelect, correctIndices: [2], explanation: "The name and instructions of the actions"),
        Question(id: "40", question: "Sunrays Limited (SL) is implementing a Retrieval Augmented Generation (RAG) solution where the knowledge store contains Spanish articles, but users will query the agent in French and English. The Agentforce Specialist needs to ensure the retriever can accurately find relevant articles despite the language differences.\nWhat should the specialist do to meet this requirement?", options: [("A", "Use the multilingual-e5-large embedding model for French and Spanish language users."), ("B", "Use the multilingual e5-large embedding model for French and English language users."), ("C", "Use the multilingual-e5-large embedding model to handle all languages.")], questionType: .singleSelect, correctIndices: [2], explanation: "Use the multilingual-e5-large embedding model to handle all languages."),
        Question(id: "41", question: "Sunrays Limited (SL) wants its Agentforce Service Agent to retrieve up to date factual data from the internet.\nWhich step must an Agentforce Specialist take to ensure the agent uses the web search capability properly?", options: [("A", "Enable the Answer Questions with Knowledge standard action specifically on the General FAQ subagent (formerly known as a topic)."), ("B", "Map the web search retriever to a custom search index in Data 360 before activating the agent."), ("C", "Remove the default General FAQ subagent (formerly known as a topic) from the agent and replace its function with a new General Web Search topic.")], questionType: .singleSelect, correctIndices: [2], explanation: "Remove the default General FAQ subagent (formerly known as a topic) from the agent and replace its function with a new General Web Search topic."),
        Question(id: "42", question: "Sunrays Limited (SL)' agent must always look up the customer's account tier and open cases from Salesforce before deciding how to respond.\nBased on Agent Script flow of control, what is true about executing deterministic actions at the very start of a subagent (formerly known as a topic)?", options: [("A", "Actions can only be guaranteed to run by placing them in the config block."), ("B", "Only before_reasoning can guarantee the large language model (LLM) is invoked before an action runs."), ("C", "The first instruction in reasoning.instructions always runs before the large language model (LLM) is invoked.")], questionType: .singleSelect, correctIndices: [2], explanation: "The first instruction in reasoning.instructions always runs before the LLM is invoked. In Agent Script, the first instruction in the reasoning.instructions block executes deterministically before the LLM begins its reasoning, making it the correct place to put mandatory lookup actions."),
        Question(id: "43", question: "An Agentforce Specialist is evaluating an agent conversation.  What is the reason why intents and session metrics within Observability are important to consider?", options: [("A", "To evaluate the agent's overall performance"), ("B", "To evaluate why the agent was unable to answer a user's question"), ("C", "To evaluate the deflection rate of the agent")], questionType: .singleSelect, correctIndices: [0], explanation: "To evaluate the agent's overall performance"),
        Question(id: "44", question: "Sunrays Limited (SL) has successfully chunked and vectorized its unstructured meeting notes into a Data 360 search index.  An Agentforce Specialist needs to connect this data to a prompt template to dynamically refine search criteria and retrieve the most relevant information.\nHow should the specialist achieve this?", options: [("A", "Create a Flex template referencing a data lake object (DLO)."), ("B", "Create a Flex template referencing a retriever in the prompt template."), ("C", "Create a Flex template referencing the data model object (DMO).")], questionType: .singleSelect, correctIndices: [1], explanation: "Create a Flex template referencing a retriever in the prompt template."),
        Question(id: "45", question: "During a code review, a junior developer asks why the Agentforce Specialist called the action using the run @actions.name command instead of simply listing the action under the reasoning.actions: block.\nWhat must the Agentforce Specialist explain regarding the difference between these two invocation methods?", options: [("A", "Both patterns execute the action on every turn automatically; the difference is purely syntactic, as the run command is simply the newer notation for Agent Script."), ("B", "The run command is only valid when nested inside reasoning.actions: blocks to pass parameters; the Agentforce Specialist must list it under reasoning.actions: for the large language model (LLM) to access it."), ("C", "Listing an action under reasoning.actions: makes it a subjective tool that the large language model (LLM) decides whether to call, calling it with the run command forces guaranteed execution every time.")], questionType: .singleSelect, correctIndices: [2], explanation: "Listing an action under reasoning.actions: makes it a subjective tool that the large language model (LLM) decides whether to call, calling it with the run command forces guaranteed execution every time."),
        Question(id: "46", question: "Sunrays Limited (SL) would like to route SMS text messages to a service rep from an Agentforce Service Agent.\nWhich service channel should the company use in the flow to ensure it's routed properly?", options: [("A", "Live Agent"), ("B", "Messaging"), ("C", "Route work action")], questionType: .singleSelect, correctIndices: [1], explanation: "Messaging"),
        Question(id: "47", question: "Sunrays Limited (SL) uses a file upload-based data library and custom prompt to support AI-driven training content. However, users report that AI frequently returns outdated documents.Which corrective action should SL implement to improve content relevancy?", options: [("A", "Switch the data library source from file uploads to a knowledge-based data library, because Salesforce knowledge bases automatically manage document recency, ensuring current documents are returned."), ("B", "Configure a custom retriever that includes a filter condition limiting retrieval to documents updated within a defined recent period, ensuring that only current content is used for AI responses."), ("C", "Continue using the default retriever without filters, because periodic reuploads will eventually phase out outdated documents without further configuration or the need for custom retrievers")], questionType: .singleSelect, correctIndices: [1], explanation: "Configure a custom retriever that includes a filter condition limiting retrieval to documents updated within a defined recent period, ensuring that only current content is used for AI responses.\nAnswer 1 is incorrect: Switching to a Salesforce Knowledge base does not automatically fix document recency by magic. While Knowledge has native version control features, a standard vector retriever searching a Knowledge DMO will still match stale published articles based on semantic score unless you explicitly configure data categories or filter rules to gate the output."),
        Question(id: "48", question: "Sunrays Limited (SL) wants to deploy an Agentforce Service Agent to support customers via a web experience. SL uses a Digital Experience site and wants to enable messaging for logged-in users. The customer needs to pass the membership number to the agent for which a pre-chat variable is available.\nWhat is a required step to connect the agent to the Digital Experience site using Messaging for In-App and Web?", options: [("A", "Configure MuleSoft to establish a secure API tunnel between the agent and the Digital Experience site."), ("B", "Configure a messaging Lightning web component using standard or custom Lightning Type for Agentforce."), ("C", "Create an Omni-Channel flow that routes messages to the agent.")], questionType: .singleSelect, correctIndices: [2], explanation: "Create an Omni-Channel flow that routes messages to the agent."),
        Question(id: "49", question: "Sunrays Limited (SL) wants to integrate its agent with its custom website. The goal is for customers to interact with the custom agent chat interface.\nWhich approach provides the framework for the custom web application to communicate with the agent?", options: [("A", "Agent API"), ("B", "Model Context Protocol (MCP)"), ("C", "Agent to Agent (A2")], questionType: .singleSelect, correctIndices: [0], explanation: "Agent API"),
        Question(id: "50", question: "Sunrays Limited (SL) plans to answer questions based on similar cases that have been successfully resolved in the past.\nWhat should SL consider when implementing this approach?", options: [("A", "No action is needed, as past cases are used to answer the question."), ("B", "Create an unstructured data model object (UDMO) based on Case object and create an index on it."), ("C", "Create a data model object (DMO) based on Case object and create an index on it.")], questionType: .singleSelect, correctIndices: [1], explanation: "Create an unstructured data model object (UDMO) based on Case object and create an index on it.\nWhile a Case is a structured record in Salesforce, the specific \"knowledge\" needed to resolve future issues is trapped in long-form text fields. When Sunrays Limited (SL) wants to use past resolved cases to generate answers, the AI needs to process \"unstructured\" content—such as case descriptions, resolution notes, and agent-customer conversations."),
        Question(id: "51", question: "Sunrays Limited (SL) is uploading thousands of new HTML knowledge articles files for a resort launch.\nTo ensure Agentforce retrieves accurate responses quickly, which chunking strategy should be used when creating a new index?", options: [("A", "Conversation-based chunking"), ("B", "Semantic based passage extraction"), ("C", "Section-aware chunking")], questionType: .singleSelect, correctIndices: [2], explanation: "Section-Aware Chunking"),
        Question(id: "52", question: "Sunrays Limited (SL) sees that the agent forgot the dietary/activity preferences gathered earlier.\nThey need those preferences to persist throughout the session.\nWhat should SL implement?", options: [("A", "Configure custom variables to capture/store customer preferences from action outputs."), ("B", "Rely on natural conversation memory and instruct the agent to look back."), ("C", "Create a context variable to capture/store customer preferences as action outputs.")], questionType: .singleSelect, correctIndices: [0], explanation: "Configure custom variables to capture/store customer preferences from action outputs.\nContext Variables are system-generated variables that hold predefined information about the user and the ongoing interaction session (such as UserId, EndUserLanguage, or Routable Id pulled from the channel's MessagingSession). They are typically read-only or set automatically by the platform upon initialization. They are not custom-created slots designed to capture arbitrary application-specific data returned from action outputs."),
        Question(id: "53", question: "A developer is using the Salesforce CLI to deploy agent components from a sandbox to production. They recently made a change to several topics, instructions, and actions.\nWhich metadata component should the developer include in their package.xml file that contains all of the topics and actions an agent will interact with?", options: [("A", "EinsteinAiPlannerBundle"), ("B", "genAiPlannerBundle"), ("C", "BotBundle")], questionType: .singleSelect, correctIndices: [1], explanation: "genAiPlannerBundle"),
        Question(id: "54", question: "Which best practice should the Agentforce Specialist follow when creating the Flex prompt template?", options: [("A", "Provide the large language model (LLM) with contextual information and give it a role such as a sales or support rep."), ("B", "Ground the large language model (LLM) with a retriever and create a custom field to store the LLM-generated response."), ("C", "Ground the large language model (LLM) with account data and create a custom field account summary to store the LLM-generated response.")], questionType: .singleSelect, correctIndices: [0], explanation: "Provide the large language model (LLM) with contextual information and give it a role such as a sales or support rep."),
        Question(id: "55", question: "An Agentforce Specialist is preparing to upload several PDF policy documents to a new file-based Agentforce Data Library.\nTo leverage advanced processing with Intelligent Context, how should the Agentforce Specialist proceed?", options: [("A", "Upload up to five PDFs that are 100 MB or less to allow the system to evaluate the optimal indexing configuration."), ("B", "Upload up to five PDFs that are 10 MB or less to allow the system to evaluate the optimal indexing configuration."), ("C", "Manually enable Intelligent Context in Data 360 prior to uploading the PDF files.")], questionType: .singleSelect, correctIndices: [1], explanation: "Upload up to five PDFs that are 10 MB or less to allow the system to evaluate the optimal indexing configuration.\nWhile you can upload PDFs up to 100 MB into the library for standard text extraction, files over 10 MB will not trigger the advanced Intelligent Context pipeline"),
        Question(id: "56", question: "Sunrays Limited (SL) is building a custom agent and creating a new Apex action that accepts a collection of text values (such as a list of product names) as an input parameter.\nWhen defining this input, which complex_data_type_name should the Agentforce Specialist use?", options: [("A", "lightning__textType"), ("B", "apex__String"), ("C", "lightning__stringType")], questionType: .singleSelect, correctIndices: [0], explanation: "lightning__textType\nlightning__textType is the correct complex_data_type_name to use when defining an input parameter that accepts a collection of text values in a custom Apex action for Agentforce."),
        Question(id: "57", question: "Universal Containers is developing an Agentforce Service Agent to handle a complex, multi-step customer onboarding process.\nDuring testing of subagents, when the agent transitions to this new subagent mid-conversation, the conversation occasionally stalls or behaves unexpectedly.\nWhat is the risk the Agentforce Specialist must consider regarding the execution timing of before_reasoning?", options: [("A", "The before_reasoning block only runs on the very first turn after the agent launches."), ("B", "The before_reasoning block will only run once and sets the immutable variables."), ("C", "The before_reasoning block runs at the start of the next turn after a transition.")], questionType: .singleSelect, correctIndices: [2], explanation: "The before_reasoning block runs at the start of the next turn after a transition.\nThe before_reasoning block of the new subagent does not fire retroactively on the transition turn itself. Instead, it is scheduled to execute at the very beginning of the next conversational turn, immediately upon receiving the user's next prompt response."),
        Question(id: "58", question: "During configuration, Sunrays Limited (SL) forgot to grant Knowledge access to the Agentforce Service Agent.\nWhich permission must SL add for the agent to interact with Knowledge articles and answer customer questions effectively?", options: [("A", "Allow View Knowledge and Run Flows"), ("B", "Access Knowledge records and fields, and Allow View Knowledge"), ("C", "Access Custom Objects and Manage External Users")], questionType: .singleSelect, correctIndices: [1], explanation: "Access Knowledge records and fields, and Allow View Knowledge\nWhile the agent might use flows for other actions, it is not the core permission required for the agent to specifically interact with the Knowledge base for answering questions."),
        Question(id: "59", question: "Sunrays Limited (SL) plans to enable Agentforce in Slack so teams can interact with agents directly in Slack channels.Which description represents the key steps required to enable Agentforce in Slack?", options: [("A", "Enable the default Slack channel Agentforce, and assign Slack agent access to users."), ("B", "Configure the Slack workflow to invoke the Agentforce API, enabling users to interact with agents through predefined triggers and automated steps."), ("C", "Configure the Slack agent connection and, in Manage Agentforce, install the agent, then assign agent access to users.")], questionType: .singleSelect, correctIndices: [2], explanation: "Configure the Slack agent connection and, in Manage Agentforce, install the agent, then assign agent access to users."),
        Question(id: "60", question: "Sunrays Limited (SL) has set up a Service Agent to allow customers to look up their order status. The topic setup includes: Name, Classification Description, Scope.Which information will be used by the Agentforce reasoning engine to choose this topic?", options: [("A", "Topic Name and Classification Description"), ("B", "Topic Name and Scope"), ("C", "Classification Description and Scope")], questionType: .singleSelect, correctIndices: [0], explanation: "Topic Name and Classification Description. The Agentforce reasoning engine uses the Topic Name and Classification Description to determine which topic to select for a user's request."),
        Question(id: "61", question: "Sunrays Limited (SL) needs to bring individual customer warranties from an external system into the Data Cloud. They want Agentforce to return warranty-related responses only for accounts whose warranty status is active.\nWhich search approach should the Agentforce Specialist configure to ensure warranty-related information is retrieved correctly?", options: [("A", "Depend on Agentforce instructions to enforce warranty constraints and include only WarrantyStatus = Active results."), ("B", "Store the account's warranty status in an Agentforce custom variable to dynamically filter warranties during retrieval."), ("C", "Use Hybrid Search and apply pre-filtering in a new custom retriever for matching accounts and where the WarrantyStatus = Active field.")], questionType: .singleSelect, correctIndices: [2], explanation: "Use Hybrid Search and apply pre-filtering in a new custom retriever for matching accounts and where the WarrantyStatus = Active field.\nTo ensure an AI agent acts with determinism and adheres to strict business rules (like only showing \"Active\" warranties), you must filter the data before it ever reaches the Large Language Model (LLM)."),
        Question(id: "62", question: "A business stakeholder wants to use AI to generate a summary based on Data Cloud data.Which method(s) should the stakeholder use to access Data Cloud data from Prompt Builder?", options: [("A", "Accessing data model objects (DMOs) directly in Flex templates, using Data Cloud related lists, and fetching Data Cloud data using prompt-initiated flows."), ("B", "Using Data Cloud related lists and fetching Data Cloud data using prompt-initiated flows."), ("C", "Using only external APIs to import Data Cloud data into Prompt Builder.")], questionType: .singleSelect, correctIndices: [1], explanation: "Using Data Cloud related lists and fetching Data Cloud data using prompt-initiated flows.\nData Cloud Related Lists: Salesforce allows administrators to expose Data Model Objects (DMOs) directly onto standard CRM record pages as related lists. Once mapped as a related list on a core record type (like an Account or Contact), Prompt Builder can natively browse the relationship matrix and select these fields using the standard resource picker."),
        Question(id: "63", question: "Sunrays Limited (SL) is implementing Agentforce Service Agent on Email. SL made an email template and now needs to connect it to a Service Agent.\nWhat should an Agentforce Specialist recommend?", options: [("A", "Create a classic email template that defines the structure of all emails sent by the Agentforce Service Agent."), ("B", "Use the standard Draft Email Template action."), ("C", "Create a Lightning email template that defines the structure of all emails sent by the Agentforce Service Agent.")], questionType: .singleSelect, correctIndices: [1], explanation: "Use the standard Draft Email Template action."),
        Question(id: "64", question: "Which technique should the Agentforce Specialist recommend to ensure deterministic control over the order in which actions are executed?", options: [("A", "Specify the large language model (LLM) provider and version."), ("B", "Specify custom variables and filters."), ("C", "Specify the order of actions.")], questionType: .singleSelect, correctIndices: [2], explanation: "Specify the order of actions."),
        Question(id: "65", question: "Sunrays Limited (SL) is tracking web activities in the Data Cloud for a unified contact. It wants to use that information in a prompt template to help extract insights from the data.Assuming that the Contact object is one of the objects associated with the prompt template, what is a valid way for SL to do this?", options: [("A", "Create a prompt template that takes a list of all Data Cloud activity records as input to pass to the large language model (LLM)."), ("B", "Call the prompt directly from Data Cloud with a web tracking activity included in the prompt definition."), ("C", "Add the activity records as an enrichment-related list to the Contact, then pass the Contact into a prompt template workspace using related list grounding.")], questionType: .singleSelect, correctIndices: [2], explanation: "Add the activity records as an enrichment-related list to the Contact, then pass the Contact into a prompt template workspace using related list grounding."),
        Question(id: "66", question: "Sunrays Limited (SL) wants to ensure that its AI agent's responses consistently reflect the company's unique brand voice and specific quality standards beyond simple pass or fail checks.\nHow should the Agentforce Specialist configure the Testing Center to evaluate this specific criteria?", options: [("A", "Enable the Coherence quality evaluation."), ("B", "Use the default Response Evaluation metric."), ("C", "Create a custom evaluation using a large language model (LLM) judge.")], questionType: .singleSelect, correctIndices: [2], explanation: "Create a custom evaluation using a large language model (LLM) judge.\nWhen a company like Sunrays Limited needs to enforce a specialized \"brand voice\" or subjective quality standards a standard binary check won't work. By creating a custom evaluation using an LLM judge, the Specialist can program a secondary, highly focused evaluation template."),
        Question(id: "67", question: "An Agentforce Specialist is building a multi-step onboarding workflow using agent actions. The workflow includes four sequential steps: account creation, profile setup, settings configuration, and finalization. After the create_account action executes successfully, the system must immediately send a verification email without requiring an additional user interaction.\nWhich approach should the specialist use to ensure the verification email is automatically triggered after account creation?", options: [("A", "Add the send_verification logic inside the procedural instructions so it executes before profile setup finishes."), ("B", "Configure the send_verification action to be available when account_created = True and wait for the agent to call it in the next step."), ("C", "Use the keyword 'run' within the create_account action to chain the send_verification action as a follow-up.")], questionType: .singleSelect, correctIndices: [2], explanation: "Use the keyword 'run' within the create_account action to chain the send_verification action as a follow-up."),
        Question(id: "68", question: "Which useful metrics does Agentforce Observability provide to a customer service team related to a Customer Service Agent?", options: [("A", "Call deflection rates, cost per interaction, and memory consumption"), ("B", "Call deflection rates, productivity, and abandoned session rates"), ("C", "Call deflection rates, abandoned session rates, and user intent ratings")], questionType: .singleSelect, correctIndices: [1], explanation: "Call deflection rates, productivity, and abandoned session rates"),
        Question(id: "69", question: "Sunrays Limited (SL) needs to create Data 360 reports to understand agent behavior.\nWhich data lake object (DLO) represents a container capturing contiguous interactions with one or more AI agents?", options: [("A", "AIAgentInteraction"), ("B", "AIAgentSession"), ("C", "AIAgentInteractionMessage")], questionType: .singleSelect, correctIndices: [1], explanation: "AIAgentSession"),
        Question(id: "70", question: "Sunrays Limited (SL) is developing a help agent that must answer customer questions by grounding prompts in data from both internal knowledge articles and an external partner portal. Which Data 360 process should the specialist review to ensure the origin of the information is accurately identified and made available?", options: [("A", "The data harmonization process, where raw data is mapped to data model objects (DMOs) and source metadata is standardized to be queried specifically by hybrid retrieves."), ("B", "The Retrieval-Augmented Generation (RAG) synthesis phase, where the large language model (LLM) automatically uses a semantic retrieve to append the source system tag to the final generated output."), ("C", "The Data 360 retriever function process, where retrieved content can be filtered based on source metadata (such as document type or author) to refine results before they are ranked using semantic or hybrid search.")], questionType: .singleSelect, correctIndices: [2], explanation: "The Data 360 retriever function process, where retrieved content can be filtered based on source metadata (such as document type or author) to refine results before they are ranked using semantic or hybrid search."),
        Question(id: "71", question: "An insurance company needs a Service Agent to ground its responses based on company-specific PDFs and a comprehensive knowledge base.\nWhich type of retriever should the Agentforce Specialist use to meet this requirement?", options: [("A", "Dynamic retriever"), ("B", "Individual retriever"), ("C", "Ensemble retriever")], questionType: .singleSelect, correctIndices: [2], explanation: "Ensemble Retriever\nWhen an agent needs to retrieve information across disparate storage formats—such as unstructured data inside company-specific PDFs alongside structured/semi-structured entries in a comprehensive knowledge base—the framework utilizes an Ensemble Retriever."),
        Question(id: "72", question: "Before deploying a Retrieval Augmented Generation (RAG) solution into production, an Agentforce Specialist wants to evaluate whether their individual custom retrievers are surfacing the most relevant chunks for specific queries without writing any code.\nWhich tool should the specialist use to test the retriever?", options: [("A", "The Retriever Playground"), ("B", "Agentforce Testing Center"), ("C", "Data 360 Query Editor")], questionType: .singleSelect, correctIndices: [0], explanation: "The Retriever Playground\nThe Retriever Playground is the dedicated, no-code, declarative workspace built explicitly to test individual retrievers in real time."),
        Question(id: "73", question: "An architect is designing an automation for standard price calculations triggered when an Opportunity is updated. The process is static, linear, and never deviates.Which tool should the architect recommend?", options: [("A", "Agentforce Agent Script"), ("B", "Agentforce Grid"), ("C", "Autolaunched Flow or Record- Triggered Flow")], questionType: .singleSelect, correctIndices: [2], explanation: "According to the Orchestration Density framework, traditional automation (Flow/Apex) should be used for rule-based, deterministic work where the execution path is fully specifiable and the outcome is predictable."),
        Question(id: "74", question: "An organization wants to process a high volume of existing CRM records to classify and summarise case notes using a single-turn generative reasoning step.Which Agentforce tool represents the best architectural fit?", options: [("A", "Agentforce Grid"), ("B", "Agentforce Service Agent"), ("C", "MuleSoft Agent Fabric")], questionType: .singleSelect, correctIndices: [0], explanation: "Agentforce Grid is designed for bulk inference use cases with low to medium orchestration complexity, rapidly processing AI tasks across existing record sets."),
        Question(id: "75", question: "An architect attempts to consolidate billing inquiries, HIPAA-compliant medical updates, and subjective sales coaching into a single monolithic agent.What is the primary risk of this Single- Agent (SOMA) anti-pattern?", options: [("A", "The agent will exceed the 75% code coverage minimum"), ("B", "The reasoning engine will suffer from contextual dilution, misclassification, and hallucinations"), ("C", "The agent will require a GenAiPlannerBundle deployment instead of a standard change set")], questionType: .singleSelect, correctIndices: [1], explanation: "The SOMA anti-pattern leads to brittle agents. Without clean conversational boundaries (Topics), the reasoning engine misclassifies intent, triggers conflicting actions, and suffers from contextual dilution causing hallucinations."),
        Question(id: "76", question: "How does the Atlas Reasoning Engine determine which Topic (subagent) to select when routing a user's prompt?", options: [("A", "By utilizing the Topic Name and the Classification Description"), ("B", "By analyzing the GenAiPlannerAttrMapping metadata"), ("C", "By executing the before_reasoning hook")], questionType: .singleSelect, correctIndices: [0], explanation: "The reasoning engine relies heavily on the Topic Name and the Classification Description to make an accurate routing choice when matching a user's prompt to a specific scope."),
        Question(id: "77", question: "An agent executes custom actions in an illogical sequence during testing. How should the architect enforce the correct sequential execution plan?", options: [("A", "Adjust the LLM temperature and top-k sampling parameters"), ("B", "Explicitly reference the dependent action's API name directly in the natural language instructions"), ("C", "Change the search index's parser to the Docling Parser")], questionType: .singleSelect, correctIndices: [1], explanation: "To force the planner service to build an accurate sequential execution plan, dependent actions must explicitly reference the action API name directly in their natural language instructions."),
        Question(id: "78", question: "In Agent Script, which of the following is true regarding indentation and structure?", options: [("A", "Nesting is determined by curly braces {}"), ("B", "The use of tab characters is the mandatory standard for depth"), ("C", "It is whitespace and indentation-sensitive, strictly discouraging the use of tab characters")], questionType: .singleSelect, correctIndices: [2], explanation: "Agent Script structurally mimics YAML. It is whitespace and indentation-sensitive, and the use of tab characters is strongly discouraged as their behavior is implementation-defined."),
        Question(id: "79", question: "In Agent Script, what is the semantic difference between the -> operator and the | (pipe) operator?", options: [("A", "-> introduces natural language prompts, while | introduces procedural logic"), ("B", "-> introduces executable procedural logic, while | introduces declarative natural language prompts"), ("C", "Both operators pass context to the EinsteinHyperClassifier")], questionType: .singleSelect, correctIndices: [1], explanation: "The -> operator introduces deterministic procedural logic guaranteed to run without LLM interpretation. The | operator introduces natural language prompts requiring the LLM's subjective interpretation."),
        Question(id: "80", question: "An architect needs to verify if a user's identity status is true before showing a 'Process Refund' tool. Which operator must be used in the conditional evaluation?", options: [("A", "=="), ("B", "="), ("C", "->")], questionType: .singleSelect, correctIndices: [0], explanation: "The double equals sign == is utilized strictly for comparison evaluation (returning a boolean), whereas the single equals sign = is an assignment operator."),
        Question(id: "81", question: "To ensure a specific tool is physically hidden from the LLM's context window until a condition is met, which Agent Script feature should be used?", options: [("A", "The | operator with strict natural language constraints"), ("B", "The `available when ` constraint"), ("C", "The `after_reasoning` hook")], questionType: .singleSelect, correctIndices: [1], explanation: "Architects must enforce deterministic gating using the `available when ` constraint, which physically hides the tool from the LLM's context window until met."),
        Question(id: "82", question: "An action must execute sequentially without any LLM probabilistic interference. How is this enforced in Agent Script?", options: [("A", "Using the `run @actions.name` command"), ("B", "Placing the action inside a flex prompt template"), ("C", "Changing the planner to AiCopilot_AgileAppDev")], questionType: .singleSelect, correctIndices: [0], explanation: "Calling an action with the `run @actions.name` command explicitly forces guaranteed execution, removing the model's probabilistic autonomy for that specific step."),
        Question(id: "83", question: "Which of the following is a strict platform constraint regarding the `before_reasoning` and `after_reasoning` lifecycle hooks?", options: [("A", "They must contain at least one | (pipe) command"), ("B", "They cannot be utilized in any subagent that employs the EinsteinHyperClassifier model"), ("C", "They require the legacy @utils.transition syntax")], questionType: .singleSelect, correctIndices: [1], explanation: "Neither before_reasoning nor after_reasoning can be utilized in any subagent that employs the EinsteinHyperClassifier model. Furthermore, they cannot contain natural language (the | command)."),
        Question(id: "84", question: "What is the correct strict syntactical requirement for calling a transition within a lifecycle hook in Agent Script?", options: [("A", "transition to @topic.name"), ("B", "@utils.transition to"), ("C", "-> transition(topic.name)")], questionType: .singleSelect, correctIndices: [0], explanation: "Within a lifecycle hook (`before_reasoning` or `after_reasoning`), the only valid transition syntax is `transition to @topic.name`. Using `@utils.transition to` inside a lifecycle hook will result in a validation failure. Outside of lifecycle hooks, `@utils.transition` remains a valid utility in the standard reasoning body."),
        Question(id: "85", question: "If a subagent transitions to a completely new subagent partway through its execution sequence, what happens to the original subagent's `after_reasoning` block?", options: [("A", "It is scheduled to evaluate upon receiving the user's next input"), ("B", "It executes concurrently with the new subagent"), ("C", "It is completely aborted and does not run")], questionType: .singleSelect, correctIndices: [2], explanation: "If an execution aborts via transition, the original subagent's after_reasoning block is completely aborted and does not run."),
        Question(id: "86", question: "A Field Generation prompt template has been activated, but users cannot see the generative AI action button on the record page. What is the cause?", options: [("A", "The field was not manually placed on the Lightning page layout in the App Builder"), ("B", "The GenAiPlannerBundle was not deployed"), ("C", "The template lacks an EinsteinSearch merge field")], questionType: .singleSelect, correctIndices: [0], explanation: "Activating a Field Generation template is only the first step; the field must be manually placed on the Lightning page layout to surface the action button to users."),
        Question(id: "87", question: "When an architect must combine disparate, unrelated data objects (e.g., Contact record and external API response) into a unified context window, which template type is used?", options: [("A", "Field Generation Template"), ("B", "Flex Template"), ("C", "Standard Prompt Template")], questionType: .singleSelect, correctIndices: [1], explanation: "Flex Templates are deployed when an architect must combine disparate, unrelated data objects into a single, unified context window."),
        Question(id: "88", question: "Which dynamic retriever is explicitly utilized by the standard 'Answer Questions with Knowledge' prompt template to pull context at runtime?", options: [("A", "{!$Input:question.results}"), ("B", "{! $EinsteinSearch:sfdc_ai_Dynamic_Retriever.results}"), ("C", "{!$Context:Knowledge.results}")], questionType: .singleSelect, correctIndices: [1], explanation: "The 'Answer Questions with Knowledge' template utilizes the dynamic retriever explicitly named `{!$EinsteinSearch:sfdc_ai_Dynamic_Retriever.results}`."),
        Question(id: "89", question: "How does the Agentforce reasoning engine ensure that irrelevant context is excluded to reduce token costs and latency?", options: [("A", "By executing Apex limits checks"), ("B", "By utilizing Relevancy Ranking to surface the most pertinent query results"), ("C", "By requesting a 10MB chunk size limit")], questionType: .singleSelect, correctIndices: [1], explanation: "The system employs Relevancy Ranking to surface the most pertinent query results at the top of the context window, explicitly excluding irrelevant context."),
        Question(id: "90", question: "Which security principle dictates what data an Agentforce agent can retrieve for grounding?", options: [("A", "The agent retrieves data based strictly on the System Administrator profile"), ("B", "Grounding data retrieval strictly inherits the running user's context (CRUD/FLS access)"), ("C", "The agent bypasses CRUD/FLS if invoked via a Flex Template")], questionType: .singleSelect, correctIndices: [1], explanation: "Grounding data retrieval strictly inherits the running user's context. An agent will never retrieve a record that the user lacks explicit CRUD or FLS access to view."),
        Question(id: "91", question: "During the testing phase, how should architects verify that Data Masking patterns in the Einstein Trust Layer are functioning correctly?", options: [("A", "By deploying the agent to production immediately"), ("B", "By turning off the Trust Layer and checking logs"), ("C", "By constructing prompts with fake identifiers (e.g., 'My SSN is 123-45-6789 FAKE')")], questionType: .singleSelect, correctIndices: [2], explanation: "Architects must never use real user data to test boundaries; they must construct prompts with fake identifiers to verify masking patterns function without risking data exposure."),
        Question(id: "92", question: "Which search methodology converts text into high-dimensional embeddings to map contextual meaning and synonymity?", options: [("A", "Keyword Search"), ("B", "Hybrid Search"), ("C", "Vector (Semantic) Search")], questionType: .singleSelect, correctIndices: [2], explanation: "Vector (Semantic) Search converts text into high-dimensional embeddings to map meaning, ideal for unstructured data and cross-lingual queries."),
        Question(id: "93", question: "An agent must only reference 'Active' warranties. Relying on the LLM to enforce this rule via natural language instructions is an anti-pattern. What is the correct approach?", options: [("A", "Utilize a Custom Retriever with Hybrid Search to apply pre-filtering conditions at the database level"), ("B", "Switch to the AiCopilot_ReAct planner"), ("C", "Upload the warranties as a 100MB PDF")], questionType: .singleSelect, correctIndices: [0], explanation: "To guarantee compliance, the architect must utilize a Custom Retriever with Hybrid Search to apply pre-filtering conditions at the database level, preventing restricted data from entering the context window."),
        Question(id: "94", question: "When querying across disparate storage formats simultaneously (e.g., PDFs and a Knowledge base), which framework is utilized?", options: [("A", "Single Intent Classifier"), ("B", "Ensemble Retriever"), ("C", "Field Generation Template")], questionType: .singleSelect, correctIndices: [1], explanation: "When querying across disparate storage formats simultaneously, an Ensemble Retriever is required to stitch the various data sources together."),
        Question(id: "95", question: "RAG testing reveals that tabular data and pricing grids are scattering across multiple disjointed chunks. What is the corrective architectural action?", options: [("A", "Change the search index's parser to the Docling Parser"), ("B", "Reduce the PDF file size to under 100MB"), ("C", "Use a Keyword Search instead of a Vector Search")], questionType: .singleSelect, correctIndices: [0], explanation: "Docling is a highly specialized framework that executes layout understanding and advanced table extraction, ensuring complex document hierarchies are chunked cohesively."),
        Question(id: "96", question: "To successfully trigger the advanced Intelligent Context pipeline (such as Docling parsing) in Data Cloud, what is the maximum file size limit for a PDF upload?", options: [("A", "100 MB"), ("B", "50 MB"), ("C", "10 MB")], questionType: .singleSelect, correctIndices: [2], explanation: "While standard text extraction permits 100 MB uploads, files must be 10 MB or less to successfully trigger the advanced Intelligent Context pipeline."),
        Question(id: "97", question: "When setting up Salesforce Knowledge as a Data Library source, mapping the entire article body as the 'Identifying Field' causes severe token bloat. What should be done instead?", options: [("A", "Map the article body using apex__String"), ("B", "Select concise fields like Title or Summary as the Identifying Field"), ("C", "Use the after_reasoning hook to truncate the text")], questionType: .singleSelect, correctIndices: [1], explanation: "To ensure high-fidelity semantic retrieval without token bloat, administrators must select concise fields (like Title or Summary) as Identifying Fields."),
        Question(id: "98", question: "Beginning in API version 64.0 (Summer '25), what is the unified metadata container used to deploy agent templates, topics, and actions?", options: [("A", "EinsteinAiPlannerBundle"), ("B", "GenAiPlannerBundle"), ("C", "BotBundle")], questionType: .singleSelect, correctIndices: [1], explanation: "The GenAiPlannerBundle is a unified metadata container that encapsulates the entire agent template, bundling referenced topics and actions to eliminate missing dependency errors."),
        Question(id: "99", question: "How does the GenAiPlannerBundle manage strict security propagation to securely pass sensitive data between tools without relying on user-provided inputs?", options: [("A", "By executing Data Masking on every user utterance"), ("B", "Via attributeMappings (GenAiPlannerAttrMapping)"), ("C", "By disabling the after_reasoning hook")], questionType: .singleSelect, correctIndices: [1], explanation: "The bundle manages strict security via attributeMappings, mapping the output of one action directly into the input of another, bypassing untrusted user inputs."),
        Question(id: "100", question: "An Apex class is strictly invoked by an autonomous AI agent rather than a human user. What is the minimum code coverage requirement for deployment to production?", options: [("A", "0%"), ("B", "50%"), ("C", "75%")], questionType: .singleSelect, correctIndices: [2], explanation: "Salesforce enforces a non-negotiable 75% minimum code coverage rule for all Apex deployments to production, regardless of whether it is invoked by a human or an AI agent."),
        Question(id: "101", question: "Which Data Model Object (DMO) captures the conversational flow, user input text, subagent routing choices, and the final generative text response at the Planner Level?", options: [("A", "ssot__AiAgentInteraction__dlm"), ("B", "ssot__TelemetryTraceSpan__dlm"), ("C", "ssot_OperationName__c")], questionType: .singleSelect, correctIndices: [0], explanation: "Agentforce Session Tracing captures conversational flow in the ssot__AiAgentInteraction__dlm object to understand what the agent decided to say."),
        Question(id: "102", question: "To debug backend execution state, individual LLM calls, and Flow execution durations at the Service Level, which Data Model Object (DMO) is used?", options: [("A", "ssot__TelemetryTraceSpan__dlm"), ("B", "ssot_AiAgentSession_dlm"), ("C", "ssot_AgentScript_dlm")], questionType: .singleSelect, correctIndices: [0], explanation: "Agent Platform Tracing captures granular backend execution state in the ssot__TelemetryTraceSpan__dlm object to understand how the agent executed tasks and why it failed."),
        Question(id: "103", question: "Agent Platform Tracing operates on which open-source standard to construct a hierarchical trace tree?", options: [("A", "Model Context Protocol (MCP)"), ("B", "OpenTelemetry (OTEL)"), ("C", "Agent-to-Agent Protocol (A2A)")], questionType: .singleSelect, correctIndices: [1], explanation: "Agent Platform Tracing operates on the open-source OpenTelemetry (OTEL) standard, where every service generates a span linking to its parent to build a trace tree."),
        Question(id: "104", question: "An architect is debugging an agent where a flow silently failed to find a record. Which span attribute reveals that a database lookup returned empty?", options: [("A", "db.operation.name=query and db.rows_affected=0"), ("B", "error.code=404"), ("C", "llm.hallucination=true")], questionType: .singleSelect, correctIndices: [0], explanation: "The span attributes explicitly reveal database lookup results; `db.rows_affected=0` indicates the query returned empty, starving the LLM of context."),
        Question(id: "105", question: "Which open-source visualizer renders trace data into a Directed Acyclic Graph (DAG) and a Finite State Machine (FSM) to map internal subagent decisions?", options: [("A", "Testing Center"), ("B", "AgentLens"), ("C", "Model Playground")], questionType: .singleSelect, correctIndices: [1], explanation: "AgentLens renders trace JSON into a DAG and FSM to visualize subagent communications, tool invocations, and LLM retries."),
        Question(id: "106", question: "If an Agentforce agent must securely query real-time inventory from an external siloed SAP system without building brittle point-to-point APIs, which protocol is the correct choice?", options: [("A", "Agent- to-Agent Protocol (A2A)"), ("B", "Model Context Protocol (MCP)"), ("C", "Simple Object Access Protocol (SOAP)")], questionType: .singleSelect, correctIndices: [1], explanation: "The Model Context Protocol (MCP) acts as a secure bridge between AI models and external enterprise tools, standardizing external tool discovery."),
        Question(id: "107", question: "Which protocol defines the horizontal communication matrix allowing distinct, autonomous agents to negotiate, delegate, and share state with one another?", options: [("A", "Agent-to-Agent Protocol (A2A)"), ("B", "Model Context Protocol (MCP)"), ("C", "Advanced Message Queuing Protocol (AMQP)")], questionType: .singleSelect, correctIndices: [0], explanation: "The Agent-to-Agent Protocol (A2A) allows distinct autonomous agents to negotiate, delegate, and share state (e.g., handing off a task to a Partner Agent)."),
        Question(id: "108", question: "Which advanced reasoning architecture loads domain knowledge, regulatory frameworks, and historical logic first to build a structural map of what causes what?", options: [("A", "ReAct Loop"), ("B", "Causal Knowledge Graph (Daisy++/NovaQ)"), ("C", "Probabilistic Neural Network")], questionType: .singleSelect, correctIndices: [1], explanation: "The Daisy platform leverages the NovaQ Reasoning Engine and a Causal Knowledge Graph to load domain knowledge and regulatory frameworks first, ensuring deterministic and explainable AI."),
        Question(id: "109", question: "What are the five key stages of the Agent Development Lifecycle?", options: [("A", "Design, Build, Code, Test, Deploy"), ("B", "Ideate, Build, Test, Deploy, Monitor"), ("C", "Plan, Script, RAG, Deploy, Optimize")], questionType: .singleSelect, correctIndices: [1], explanation: "The five key stages of the Agent Development Lifecycle are Ideate, Build, Test, Deploy, and Monitor."),
        Question(id: "110", question: "An organization separates agents into field service, support, and sales that all roll up to an Employee Superagent. Which decomposition strategy is this?", options: [("A", "Decomposition by Workflow Stage"), ("B", "Decomposition by Domain Expertise"), ("C", "Decomposition by Capability")], questionType: .singleSelect, correctIndices: [1], explanation: "Decomposing by Domain Expertise splits agents based on knowledge domains that mirror the organization's structure."),
        Question(id: "111", question: "An organization has a contract placement Superagent that routes to a Matching Agent, then a Notification Agent, then a Scheduling Agent. Which decomposition strategy is this?", options: [("A", "Decomposition by Workflow Stage"), ("B", "Decomposition by Domain Expertise"), ("C", "Decomposition by Capability")], questionType: .singleSelect, correctIndices: [0], explanation: "Decomposing by Workflow Stage is used when work has a fixed sequence (Step A always comes before Step B)."),
        Question(id: "112", question: "Which of the following describes the Orchestrator (Pattern 3) multi-agent orchestration pattern?", options: [("A", "A single agent routes via intent classifier to multiple subagents"), ("B", "The orchestrator is the single entry point, collects results from multiple independent agents, and responds to the user"), ("C", "Agents communicate peer-to-peer without an orchestrator")], questionType: .singleSelect, correctIndices: [1], explanation: "In Pattern 3, the Orchestrator Agent is the single entry point that delegates to multiple independent agents, collects results, and responds to the user. It has higher latency but high modularity."),
        Question(id: "113", question: "In the context of the Atlas Reasoning Engine's memory, what does 'State' refer to?", options: [("A", "The sequence of actions executed by the agent"), ("B", "Persistent outputs like CRM record updates"), ("C", "The agent's ability to maintain a stable context with an individual user, including past exchanges")], questionType: .singleSelect, correctIndices: [2], explanation: "State refers to the agent's ability to maintain a stable context with an individual user, including past exchanges, current session interactions, and user-specific data."),
        Question(id: "114", question: "In the context of the Atlas Reasoning Engine's memory, what does 'Side Effects' refer to?", options: [("A", "Changes made to the conversation history"), ("B", "The persistent outputs of the agent flow, such as CRM record updates or sent emails"), ("C", "Hallucinations generated by the LLM")], questionType: .singleSelect, correctIndices: [1], explanation: "Side effects are the persistent outputs of the agent flow, taking the form of CRM record updates, sent email messages, and other tangible system changes."),
        Question(id: "115", question: "If Atlas Reasoning Engine is considered the brain of Agentforce, which component is considered its 'conscience', responsible for ethical and trusted behavior?", options: [("A", "Agent Builder"), ("B", "Einstein Trust Layer"), ("C", "Data Cloud")], questionType: .singleSelect, correctIndices: [1], explanation: "The Einstein Trust Layer provides the built-in guardrails, data masking, and ethical frameworks that ensure agents act responsibly and securely."),
        Question(id: "116", question: "Compared to standard generative chatbots, Agentforce agents utilize inference-time reasoning to deliberately formulate answers. What type of thinking does this represent?", options: [("A", "System 1 Thinking"), ("B", "System 2 Thinking"), ("C", "Heuristic Thinking")], questionType: .singleSelect, correctIndices: [1], explanation: "Atlas Reasoning Engine engages in inference-time System 2 thinking, taking its time to deduce intent, retrieve data, and iteratively formulate an answer rather than churning out an immediate reactive response."),
        Question(id: "117", question: "Which feature of the Atlas Reasoning Engine allows it to explain its outputs and underlying assumptions through a dialogue with the user?", options: [("A", "Conversational Explainability"), ("B", "Hallucination Prevention"), ("C", "Zero-Copy Data Integration")], questionType: .singleSelect, correctIndices: [0], explanation: "Conversational explainability enables the agent to explain its thought process and assumptions interactively, separating it from LLMs that only provide static responses."),
        Question(id: "118", question: "Which system subagent acts as the single entry point for an agent, reading every message and deciding where it belongs?", options: [("A", "Ambiguous Question"), ("B", "Escalation"), ("C", "Agent Router")], questionType: .singleSelect, correctIndices: [2], explanation: "The Agent Router is a system subagent added to all agents. It serves as the single entry point that evaluates the user's input and routes it to the most appropriate standard or custom subagent."),
        Question(id: "119", question: "Why is the Single-Agent (SOMA) architecture considered an anti-pattern for highly complex, varied enterprise tasks?", options: [("A", "It results in instruction overload and forces the reasoning engine to context-switch, degrading quality"), ("B", "It requires excessive API calls to external systems"), ("C", "It bypasses the Einstein Trust layer")], questionType: .singleSelect, correctIndices: [0], explanation: "When a single subagent's instructions become too long or mix fundamentally different jobs, the reasoning engine loses focus, context-switches, and quality degrades."),
        Question(id: "120", question: "What is the passing score for the Salesforce Certified Agentforce Specialist exam?", options: [("A", "65%"), ("B", "72%"), ("C", "80%")], questionType: .singleSelect, correctIndices: [1], explanation: "According to the official Exam Guide, the passing score is 72%."),
        Question(id: "121", question: "Which Agentforce tool provides an integration fabric, governance layer, and cross-system orchestration foundation via API-led connectivity?", options: [("A", "MuleSoft Agent Fabric"), ("B", "Agentforce Operations"), ("C", "Agentforce Grid")], questionType: .singleSelect, correctIndices: [0], explanation: "MuleSoft Agent Fabric serves as the integration fabric and governance layer for connecting agentic workflows across enterprise systems."),
        Question(id: "122", question: "Which tool is designed to streamline and automate back-office business processes such as high-volume document processing and multi-party orchestration?", options: [("A", "Agentforce Grid"), ("B", "Agentforce Operations"), ("C", "Data 360")], questionType: .singleSelect, correctIndices: [1], explanation: "Agentforce Operations (formerly Agentforce Supply Chain) is an AI-powered collaborative workflow orchestration platform designed for back-office process automation."),
        Question(id: "123", question: "What is the maximum amount of time allotted to complete the Agentforce Specialist exam?", options: [("A", "90 minutes"), ("B", "105 minutes"), ("C", "120 minutes")], questionType: .singleSelect, correctIndices: [1], explanation: "Candidates are allotted exactly 105 minutes to complete the assessment."),
        Question(id: "124", question: "Attempting to use the `always_expect_input` property in the current compiler release of Agent Script will result in what outcome?", options: [("A", "A warning message during deployment"), ("B", "The LLM pausing indefinitely"), ("C", "A compiler validation failure/deployment failure")], questionType: .singleSelect, correctIndices: [2], explanation: "Utilizing properties like `always_expect_input` that are actively blocked by the current compiler release will cause deployment failures and represent explicit platform rule violations."),
        Question(id: "125", question: "When using Data Explorer to verify unstructured data ingestion for RAG, what column should be checked to ensure paragraphs and headers are not cut off incorrectly?", options: [("A", "Source Data Model Object"), ("B", "Chunk Text (or Chunk)"), ("C", "Citations")], questionType: .singleSelect, correctIndices: [1], explanation: "The 'Chunk Text' column in the Data Explorer shows the individual segments generated from the document. If headers are separated from body text, retrieval will be poor."),
        Question(id: "126", question: "In the context of the Testing Center, which two Response Quality Evaluations assess how well a response is communicated, ensuring it is clear and structured?", options: [("A", "Speed and Accuracy"), ("B", "Completeness and Coherence"), ("C", "Toxicity and Safety")], questionType: .singleSelect, correctIndices: [1], explanation: "Completeness and Coherence are used in Response Quality Evaluations to ensure the response is clear, well-structured, and aligned with the desired customer experience."),
        Question(id: "127", question: "An administrator uploads a 50MB PDF into an Agentforce Data Library using standard text extraction. Will it trigger the advanced Intelligent Context pipeline (Docling)?", options: [("A", "Yes, because it is under 100MB"), ("B", "No, because files over 10MB do not trigger the advanced pipeline"), ("C", "Yes, because it is a PDF format")], questionType: .singleSelect, correctIndices: [1], explanation: "While standard text extraction permits uploads up to 100MB, files must be 10MB or less to trigger the advanced Intelligent Context pipeline."),
        Question(id: "128", question: "An architect needs an agent to execute tasks where the goal is predefined, but intermediate steps require runtime context and user intent. Which architectural standard fits best?", options: [("A", "Traditional Automation (Flow)"), ("B", "Agentforce Grid"), ("C", "Agent Script")], questionType: .singleSelect, correctIndices: [2], explanation: "For high orchestration density where the execution path is partially or non-specifiable and requires reasoning, Agent Script balances deterministic control with runtime reasoning."),
        Question(id: "129", question: "Why is testing an agent with real user PII a violation of Agent Development Lifecycle best practices?", options: [("A", "The Einstein Trust Layer will automatically delete the testing session"), ("B", "It risks data exposure; fake identifiers must be used to verify masking patterns safely"), ("C", "PII cannot be processed by any LLM under any circumstances")], questionType: .singleSelect, correctIndices: [1], explanation: "Architects must never use real user data to test boundaries. They must construct prompts with fake identifiers to verify masking patterns without risking data exposure."),
        Question(id: "130", question: "When deploying a prompt template from sandbox to production, what ensures that unrelated objects can be used in the same context window?", options: [("A", "Using a Flex Prompt Template"), ("B", "Using a Field Generation Prompt Template"), ("C", "Using a Record Summary Prompt Template")], questionType: .singleSelect, correctIndices: [0], explanation: "Flex Templates allow architects to combine disparate, unrelated data objects into a unified context window."),
        Question(id: "131", question: "If an execution path is 100% predictable based on record state, which tool provides the fastest delivery and easiest maintenance?", options: [("A", "Agent Script"), ("B", "Flow (Traditional Automation)"), ("C", "Agentforce Operations")], questionType: .singleSelect, correctIndices: [1], explanation: "Traditional automation (Flow) is recommended for deterministic, 100% predictable paths. Using Agentforce for purely deterministic logic without reasoning is an anti-pattern."),
        Question(id: "132", question: "An organization wants to process a high-volume document ingestion flow that handles variances, partial matches, and requires reasoning per document rather than uniform single-turn inference. Which tool is best?", options: [("A", "Agentforce Grid"), ("B", "Agentforce Operations"), ("C", "Record-Triggered Flow")], questionType: .singleSelect, correctIndices: [1], explanation: "Agentforce Operations is designed for medium-density, intent-driven high-volume document processing where reasoning is required per record (exception handling, partial matches)."),
        Question(id: "133", question: "A developer writes a natural language prompt inside a `before_reasoning` block. What will happen?", options: [("A", "The LLM will process the prompt before checking constraints"), ("B", "The compiler will fail, as lifecycle hooks cannot contain natural language instructions"), ("C", "The prompt will override the subagent's main instructions")], questionType: .singleSelect, correctIndices: [1], explanation: "Neither the `before_reasoning` nor `after_reasoning` hooks can contain natural language (the `|` pipe command). They are strictly reserved for deterministic logic."),
        Question(id: "134", question: "What happens if a custom action's natural language instructions fail to explicitly reference its dependent action's API name?", options: [("A", "The planner service may pick up actions in the incorrect sequential order"), ("B", "The action will bypass the Einstein Trust Layer"), ("C", "The system will throw a GenAiPlannerAttrMapping error")], questionType: .singleSelect, correctIndices: [0], explanation: "To ensure the planner service builds an accurate sequential execution plan, dependent actions must explicitly reference the action API name directly in their instructions."),
        Question(id: "135", question: "What is the primary diagnostic purpose of the `ssot__TelemetryTraceSpan__dlm` object in Data Cloud?", options: [("A", "To capture the user's input text and the final generative response"), ("B", "To capture granular backend execution state, including individual LLM calls and Flow durations"), ("C", "To store billing metrics for Einstein Requests")], questionType: .singleSelect, correctIndices: [1], explanation: "Agent Platform Tracing writes to `ssot__TelemetryTraceSpan__dlm` to capture granular backend execution state, allowing architects to understand how the agent executed tasks and why it failed.")
    ]
